function validate([keyName, keyTime]) {
  if (!Array.isArray(keyName) || !Array.isArray(keyTime)) return 'keyName and keyTime are lists of strings.';
  if (keyName.length < 1 || keyName.length > 100000) return 'There must be 1 to 10^5 swipes.';
  if (keyName.length !== keyTime.length) return 'keyName and keyTime must have the same length.';
  const seen = new Set();
  for (let i = 0; i < keyName.length; i++) {
    if (typeof keyName[i] !== 'string' || !/^[a-z]{1,10}$/.test(keyName[i])) return 'Each name has 1 to 10 lowercase letters.';
    const match = typeof keyTime[i] === 'string' && /^(\d\d):(\d\d)$/.exec(keyTime[i]);
    if (!match || Number(match[1]) > 23 || Number(match[2]) > 59) return 'Each time is a valid "HH:MM" from 00:00 to 23:59.';
    const pair = `${keyName[i]} ${keyTime[i]}`;
    if (seen.has(pair)) return 'The same name and time may not appear twice.';
    seen.add(pair);
  }
  return null;
}

