function alertNames(keyName, keyTime) {
  const times = new Map();
  for (let i = 0; i < keyName.length; i++) {
    const [hours, minutes] = keyTime[i].split(':');
    const minute = Number(hours) * 60 + Number(minutes);
    if (!times.has(keyName[i])) {
      times.set(keyName[i], []);
    }
    times.get(keyName[i]).push(minute);
  }

  const alerted = [];
  for (const [name, list] of times) {
    list.sort((a, b) => a - b);
    for (let i = 2; i < list.length; i++) {
      if (list[i] - list[i - 2] <= 60) {
        alerted.push(name);
        break;
      }
    }
  }
  alerted.sort();
  return alerted;
}

