function alertNames(keyName, keyTime) {
  // For every swipe, count the same worker's swipes in the hour that starts at it.
  const toMinutes = t => parseInt(t.slice(0, 2), 10) * 60 + parseInt(t.slice(3), 10);
  const result = new Set();
  for (let i = 0; i < keyName.length; i++) {
    const start = toMinutes(keyTime[i]);
    let count = 0;
    for (let j = 0; j < keyName.length; j++) {
      if (keyName[j] !== keyName[i]) continue;
      const t = toMinutes(keyTime[j]);
      if (t >= start && t <= start + 60) count++;
    }
    if (count >= 3) result.add(keyName[i]);
  }
  return [...result].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
}

