function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const nameCount = large ? 100 + pick(150) : 1 + pick(4);
  const names = new Set();
  while (names.size < nameCount) {
    const length = 1 + pick(large ? 10 : 3);
    let name = '';
    for (let c = 0; c < length; c++) name += letters[pick(large ? 26 : 3)];
    names.add(name);
  }
  const pool = [...names];
  const n = large ? 2000 : 1 + pick(10);
  // A narrow span of the day makes alerts likely; the whole day makes them rare.
  const span = large ? [600, 1440][pick(2)] : [70, 120, 240, 1440][pick(4)];
  const base = pick(1440 - span + 1);
  const seen = new Set();
  const keyName = [];
  const keyTime = [];
  while (keyName.length < n) {
    const name = pool[pick(pool.length)];
    const minute = base + pick(span);
    const time = `${String(Math.floor(minute / 60)).padStart(2, '0')}:${String(minute % 60).padStart(2, '0')}`;
    if (seen.has(`${name} ${time}`)) continue;
    seen.add(`${name} ${time}`);
    keyName.push(name);
    keyTime.push(time);
  }
  return [keyName, keyTime];
}
